#define debug(...)
#define debugArr(...)
#endif

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    if(!(cin >> n)) return 0;

    vector<long long> a(n+1);
    for(int i=1;i<=n;++i) cin >> a[i];

    vector<vector<int>> adj(n+1);
    for(int i=1;i<=n-1;++i){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<long long> vals(n);
    for(int i=0;i<n;++i) vals[i] = a[i+1];
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();
    vector<int> comp(n+1);
    for(int i=1;i<=n;++i) comp[i] = int(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin()) + 1;

    vector<int> parent(n+1, 0), order;
    order.reserve(n);
    parent[1] = 0;
    {
        vector<int> st; st.reserve(n);
        st.push_back(1);
        while(!st.empty()){
            int u = st.back(); st.pop_back();
            order.push_back(u);
            for(int v: adj[u]) if(v != parent[u]){
                parent[v] = u;
                st.push_back(v);
            }
        }
    }

    vector<int> subsz(n+1, 0), heavy(n+1, -1);
    for(int i = (int)order.size()-1; i>=0; --i){
        int u = order[i];
        subsz[u] = 1;
        int best = -1, bestsz = 0;
        for(int v: adj[u]) if(v != parent[u]){
            subsz[u] += subsz[v];
            if(subsz[v] > bestsz){ bestsz = subsz[v]; best = v; }
        }
        heavy[u] = best; 
    }

    vector<int> stt(n+1), en(n+1), tour(n+1);
    int timer = 0;
    {
        vector<pair<int,int>> stk; stk.reserve(n);
        stk.push_back({1, 0});
        parent[1] = 0; 
        while(!stk.empty()){
            int u = stk.back().first;
            int &it = stk.back().second;
            if(it == 0){
                stt[u] = ++timer;
                tour[timer] = u;
            }
            if(it < (int)adj[u].size()){
                int v = adj[u][it++];
                if(v == parent[u]) continue;
                parent[v] = u;
                stk.push_back({v, 0});
            } else {
                en[u] = timer;
                stk.pop_back();
            }
        }
    }

    vector<int> cnt(m+2, 0);
    vector<int> ans(n+1, 0);
    int distinct = 0;

    auto add = [&](int node){
        int x = comp[node];
        if(++cnt[x] == 1) ++distinct;
    };
    auto remove = [&](int node){
        int x = comp[node];
        if(--cnt[x] == 0) --distinct;
    };

    function<void(int,int)> dsu = [&](int u, int keep){

        for(int v: adj[u]) if(v != parent[u] && v != heavy[u]) dsu(v, 0);

        if(heavy[u] != -1) dsu(heavy[u], 1);

        for(int v: adj[u]) if(v != parent[u] && v != heavy[u]){
            for(int t = stt[v]; t <= en[v]; ++t) add(tour[t]);
        }

        add(u);
        ans[u] = distinct;
        if(keep == 0){
            for(int t = stt[u]; t <= en[u]; ++t) remove(tour[t]);
        }
    };

    dsu(1, 1); 

    for(int i=0;i<n;++i){
        cout << ans[i+1] << (i+1==n? '\n' : ' ');
    }

}